one, 'optional': False, 'hidden': False, 'is_dynamic': False, 'value': '1', 'area': False, 'datalist': []}, {'model_class': 'IntegerToolParameter', 'name': 'MIN_ABUNDANCE', 'argument': 'MIN_ABUNDANCE', 'type': 'integer', 'label': 'Minimum abundance', 'help': 'Minimum abundance for unique sequences form new partition', 'help_format': 'html', 'refresh_on_change': False, 'min': 1, 'max': None, 'optional': False, 'hidden': False, 'is_dynamic': False, 'value': '1', 'area': False, 'datalist': []}, {'model_class': 'IntegerToolParameter', 'name': 'MAX_CLUST', 'argument': 'MAX_CLUST', 'type': 'integer', 'label': 'Maximum number of partitions', 'help': 'Once this many partitions have been created, the algorithm terminates regardless of whether the statistical model suggests more real sequence variants exist. If set to 0 this argument is ignored. Default value is 0', 'help_format': 'html', 'refresh_on_change': False, 'min': 0, 'max': None, 'optional': False, 'hidden': False, 'is_dynamic': False, 'value': '0', 'area': False, 'datalist': []}]}, {'model_class': 'Section', 'name': 'pseudo', 'type': 'section', 'title': 'pseudo-pooling behavior', 'help': None, 'expanded': False, 'inputs': [{'model_class': 'IntegerToolParameter', 'name': 'PSEUDO_PREVALENCE', 'argument': 'PSEUDO_PREVALENCE', 'type': 'integer', 'label': 'Pseudo pooling prevalence', 'help': 'All sequence variants found in at least this many samples are used as priors for a subsequent round of sample inference', 'help_format': 'html', 'refresh_on_change': False, 'min': 0, 'max': None, 'optional': False, 'hidden': False, 'is_dynamic': False, 'value': '2', 'area': False, 'datalist': []}, {'model_class': 'FloatToolParameter', 'name': 'PSEUDO_ABUNDANCE', 'argument': 'PSEUDO_ABUNDANCE', 'type': 'float', 'label': 'Pseudo pooling abundance', 'help': 'All denoised sequence variants with total abundance (over all samples) greater than this are used as priors for a subsequent round of sample inference. Default is to ignore abundan